import re

def is_valid_ip(ip):
    pattern = r'^\d+\.\d+\.\d+\.\d+$'
    return bool(re.fullmatch(pattern, ip))

print(is_valid_ip('999.999.999.999'))
print(is_valid_ip('192.168.0.1'))
